import META from '../assets/movement-fx/motion-meta-v1.json' with {type:'json'};
import {drawFrameBlend} from './fx-animation.mjs';
export async function loadMovementFx(assets,progress=()=>{}){if(assets.movementFx)return;assets.movementFx={};await Promise.all(Object.keys(META.sheets).map(file=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{assets.movementFx[file]=image;progress();resolve();};image.onerror=()=>reject(Error('职业移动特效载入失败'));image.src='assets/movement-fx/'+file;})));}
export function movementBurst(w,{hero=w.hero,kind='teleport',x=w.player.x,y=w.player.y,arrival=false}={}){w.effects.push({id:++w.serial,kind:'heroMovement',hero,movementKind:kind,arrival,x,y,age:0,visualOffset:0,duration:kind==='jump'?.5:.55});}
export function drawMovementFx(c,w,e,assets){if(e.kind!=='heroMovement')return false;const m=META.units[e.hero]?.[e.movementKind],img=assets.movementFx?.[m?.file];if(!m||!img)return false;const t=Math.min(1,e.age/e.duration),value=e.arrival?1+Math.min(1,t/.8)*2:Math.min(1,t)*3,a=Math.min(3,Math.floor(value));drawFrameBlend(c,img,m.frames,{a,b:Math.min(3,a+1),mix:value-a},e.x,e.y,e.movementKind==='jump'?145:190,{ground:true,reference:m.reference,alpha:.72*Math.min(1,t*12,(1-t)*5)});return true;}
